{"doneWhen":{"all":[{"path":"countObjects(kind=item, name=Crown)","op":">=","value":1}]},"modes":[{"id":"collect-and-craft","priority":10,"when":{"all":[{"path":"body.x","op":">=","value":0}]},"macro":"skill","params":{"name":"field-work"}}],"skills":[{"name":"field-work","skill":"async (b) => {
  const need = { Wood: 3, Stone: 2 };
  const have = { Wood: 0, Stone: 0 };
  const count = async () => {
    const items = await b.items();
    have.Wood = 0; have.Stone = 0;
    for (const it of items) {
      if (it.name === 'Wood') have.Wood += it.stack;
      if (it.name === 'Stone') have.Stone += it.stack;
    }
  };
  await count();
  b.log('start have ' + JSON.stringify(have));

  const pick = async (x, y, label) => {
    const r = await b.walkTo(x, y, 'adjacent');
    if (!r.ok) { b.log('walk fail ' + label + ' ' + r.reason); return false; }
    const p = await b.faceAndPress(x, y, 'KeyE');
    b.log('pick ' + label + ' ' + JSON.stringify(p));
    return !!(p && p.ok);
  };

  const unlock = async (x, y, label) => {
    const r = await b.walkTo(x, y, 'adjacent');
    if (!r.ok) { b.log('walk fail door ' + label + ' ' + r.reason); return false; }
    const p = await b.faceAndPress(x, y, 'KeyE');
    b.log('unlock ' + label + ' ' + JSON.stringify(p));
    return !!(p && p.ok);
  };

  // Grab keys first
  await pick(2, 2, 'Red Key');
  await pick(11, 1, 'Blue Key');

  // Wood (directly reachable)
  await pick(10, 3, 'Wood');
  await pick(10, 1, 'Wood');
  await count();

  // Stone behind blue door: unlock blue door at (8,6) then collect
  if (have.Stone < need.Stone) {
    await unlock(8, 6, 'Blue Door');
    await pick(10, 7, 'Stone');
    await pick(11, 8, 'Stone');
    await count();
  }

  // If still short on wood, try red door area
  if (have.Wood < need.Wood) {
    await unlock(8, 3, 'Red Door');
    await pick(10, 3, 'Wood');
    await pick(10, 1, 'Wood');
    await count();
  }

  b.log('final have ' + JSON.stringify(have));
  if (have.Wood < need.Wood || have.Stone < need.Stone) {
    b.log('missing materials');
    return;
  }

  const w = await b.walkTo(6, 2, 'adjacent');
  if (!w.ok) { b.log('bench walk fail ' + w.reason); return; }
  const c = await b.faceAndPress(6, 2, 'KeyC');
  b.log('craft ' + JSON.stringify(c));
}","check":"async (b) => {
  const items = await b.items();
  const crown = items.find(i => i.name === 'Crown');
  return { ok: !!crown, detail: crown ? 'Crown crafted' : 'no Crown yet' };
}"}]}
